SELECT spip.PERIODDATE AS `报告期`, spip.A_STOCKSNAME AS `股票简称`, spip.A_STOCKCODE AS `股票代码`, spip.ITEM_NAME AS `产品名称`, ROUND(spip.INCOME/10000, 3) AS `营业收入(亿元)`, spip.PRI_RVNU_PCT AS `营收占比(%)` FROM STK_PRI_INCOME_PRODUCT spip JOIN GET_A_SEC_CODE gasc ON spip.COMCODE = gasc.COMCODE AND gasc.ISVALID = 1 WHERE spip.ISVALID = 1 AND gasc.SEC_SNAME LIKE '%万华化学%' AND spip.RPT_TYPE = '合并' AND spip.PERIODDATE = '2025-12-31 00:00:00.000' AND spip.ITEM_NAME LIKE '%聚氨酯%' AND spip.PRI_RVNU_PCT IS NOT NULL ORDER BY spip.PERIODDATE DESC, spip.ITEM_NAME;
200
